  'settings.help.after.title': 'หลังการดาวน์โหลด',
  'settings.help.after.body':
    'ไฟล์บีบอัดจะถูกแตกไฟล์โดยอัตโนมัติ: zip (รวมถึงที่เข้ารหัส ทั้ง WinZip AES และ ZipCrypto รุ่นเก่า) rar ที่มีชุดหลายไฟล์ 7z tar และ gzip/bzip2/xz/zstd ไม่ว่าจะห่อ tar อยู่หรือไม่ - Go ล้วน ๆ ไม่ต้องใช้โปรแกรม unrar หรือ 7z ภายนอก สำหรับไฟล์บีบอัดที่เข้ารหัส รายการรหัสผ่านจะถูกลองตามลำดับ ไฟล์ที่เสร็จแล้วจะถูกตรวจสอบกับ checksum ใด ๆ ที่มาพร้อมกับมัน: รายการ .sfv ไฟล์ md5/sha1/sha256sum หรือ CRC32 ที่ชื่อรุ่นนั้นเองมีอยู่',
  'settings.help.after.link1': 'เปิดการตั้งค่าไฟล์บีบอัด',
