  'settings.torrents.engineNote': 'อัตราส่วนซีดเป้าหมาย ระยะเวลาซีดเป้าหมาย และพอร์ต ตอนนี้มีผลกับทุกทอร์เรนต์ที่เอนจินนี้เริ่มทำงานแล้ว - ส่วนพอร์ตนั้นมีผลเฉพาะทอร์เรนต์แรกสุดนับตั้งแต่อินสแตนซ์นี้รีสตาร์ทครั้งล่าสุดเท่านั้น เพราะไคลเอนต์ทอร์เรนต์ของเอนจินเองถูกสร้างขึ้นเพียงครั้งเดียวและจะไม่ถูกสร้างใหม่อีกเลยหลังจากนั้น ส่วนการบันทึกในภายหลังก็ยังคงถูกบันทึกอย่างถูกต้องและจะมีผลตั้งแต่การรีสตาร์ทครั้งถัดไปเป็นต้นไป ขีดจำกัดการอัปโหลดยังคงถูกบันทึกและตรวจสอบเท่านั้น โดยเอนจินยังไม่มีทางนำไปใช้กับการดาวน์โหลดที่กำลังทำงานอยู่ DHT และ PEX ด้านล่างก็อยู่ในสถานการณ์เดียวกันสำหรับทอร์เรนต์ทั่วไป (ที่ไม่ใช่ส่วนตัว) นั่นคือค่าเริ่มต้นของอินสแตนซ์นี้เองก็ยังไม่มีผลกับการดาวน์โหลดที่กำลังทำงานอยู่เช่นกัน ทอร์เรนต์จึงยังคงซีดโดยเปิดทั้งสองอย่างไว้ไม่ว่าจะตั้งค่าไว้อย่างไรที่นี่ - ส่วนทอร์เรนต์ส่วนตัวเป็นกรณีที่ต่างออกไปโดยสิ้นเชิง ดูหมายเหตุด้านล่างเพิ่มเติม ถึงอย่างนั้นปุ่มแมปด้านล่างก็ยังทำสิ่งที่เกิดขึ้นจริง: มันขอให้เราเตอร์ส่งต่อหมายเลขพอร์ตที่กรอกไว้ด้านบนอย่างตรงไปตรงมา ไม่ว่าจะมีทอร์เรนต์กำลังรับฟังอยู่ที่พอร์ตนั้นในตอนนี้หรือไม่ก็ตาม',
