  'settings.volume.title': 'เพดานปริมาณข้อมูล',
  'settings.volume.titleHint': 'ปริมาณที่อินสแตนซ์นี้ดาวน์โหลดจนเสร็จ นับเทียบกับเพดานที่คุณตั้งไว้ ต่อหนึ่งช่วงเวลา สิ่งที่นับคือขนาดที่โฮสเตอร์ประกาศไว้สำหรับการดาวน์โหลดที่เสร็จแต่ละรายการ อะไรที่เสร็จโดยไม่มีการบอกขนาดจึงนับเป็นศูนย์ และสิ่งที่ทอร์เรนต์อัปโหลดออกไปไม่ถูกนับเลย นี่คือการอ่านค่าจากการดาวน์โหลดของคุณ ไม่ใช่การวัดสายของคุณ ไม่มีอะไรตรงนี้เห็นไบต์ที่เราเตอร์ของคุณขนไปจริง ๆ',
