  'settings.downloads.idleDeploymentContainer': 'นี่ทำงานอยู่ในคอนเทนเนอร์ โพรเซสของมันคือ PID 1 ในเนมสเปซของตัวเอง การออกจึงหยุดแค่คอนเทนเนอร์และไม่หยุดอย่างอื่นเลย และมันสั่งให้เครื่องที่อยู่ข้างใต้เข้าสู่โหมดสลีปไม่ได้ เพราะไม่มีอะไรจากในคอนเทนเนอร์เอื้อมถึงสถานะพลังงานของเครื่องนั้น คอนเทนเนอร์จะกลับมาหลังการออกหรือไม่ ขึ้นอยู่กับนโยบายการรีสตาร์ทที่คุณตั้งให้มัน ไม่ใช่การตั้งค่านี้ ถ้าคุณอยากให้โฮสต์หลับ ให้ใช้คำสั่งตรงนี้ที่เอื้อมถึงโฮสต์ได้',
  'settings.downloads.idleDeploymentDesktop': 'นี่คือบิลด์เดสก์ท็อป มันจึงสั่งให้เครื่องนี้เข้าสู่โหมดสลีปได้ ส่วนการออกไม่มีให้เลือกที่นี่ เพราะหน้าต่างและไอคอนถาดระบบปิดแอปอย่างเรียบร้อยอยู่แล้ว',
  'settings.downloads.idleQuitHint': 'การออกจะปล่อยให้งานที่ยังค้างอยู่ไหลจนหมดแล้วจึงหยุดโพรเซส เหมือนกับปุ่มออกบนหน้าขั้นสูงทุกประการ ส่วนมันจะเริ่มใหม่อีกหรือไม่ เป็นเรื่องของนโยบายการรีสตาร์ทของคอนเทนเนอร์คุณ ไม่ใช่การตั้งค่านี้',
  'settings.downloads.idleSuspendHint': 'โหมดสลีปคือการขอให้ระบบปฏิบัติการพักเครื่องนี้ ใช้ได้เฉพาะที่ระบบยอมให้แอปนี้ขอเท่านั้น บน Linux ตัวจัดการสิทธิ์อาจปฏิเสธ แล้วเหตุผลจะไปอยู่ใต้การทำงานครั้งล่าสุด',
  'settings.downloads.idleCommandProgram': 'โปรแกรม',
  'settings.downloads.idleCommandProgramHint': 'พาธเต็มของโปรแกรมที่จะถูกเริ่ม มันทำงานโดยตรง ไม่ได้ผ่านเชลล์ ไปป์ การเปลี่ยนทิศทาง หรือสองคำสั่งเรียงกัน จึงต้องอยู่ในไฟล์สคริปต์ที่คุณชี้มาที่นี่แทน ไม่มีอะไรถูกแทนค่าลงไปเลย สิ่งที่คุณพิมพ์ตรงนี้คือสิ่งที่ทำงาน',
  'settings.downloads.idleCommandArgs': 'อาร์กิวเมนต์',
  'settings.downloads.idleCommandArgsHint': 'บรรทัดละหนึ่งตัว อาร์กิวเมนต์ที่มีช่องว่างอยู่ข้างในจะได้ยังเป็นอาร์กิวเมนต์เดียว',
  'settings.downloads.idleCommandTimeout': 'หยุดมันหลังจาก (วินาที)',
  'settings.downloads.idleCommandTimeoutHint': 'โปรแกรมทำงานได้นานเท่าใดก่อนจะถูกหยุด การถูกหยุดไม่ใช่เรื่องเดียวกับการล้มเหลว คำสั่งที่สั่งให้เครื่องเข้าสู่โหมดสลีปอาจถูกฆ่าระหว่างทางลง ทั้งที่ทำงานของมันเสร็จไปแล้ว',
  'settings.downloads.idleCommandSecretHint': 'บรรทัดคำสั่งถูกเก็บเป็นข้อความธรรมดาใน settings.json และติดไปกับข้อมูลสำรองทุกชุด เก็บรหัสผ่านและโทเคนออกไปให้พ้น โดยวางไว้ในไฟล์ที่มีแต่โปรแกรมนั้นอ่าน มันไม่ถูกใส่ลงในชุดข้อมูลวินิจฉัย และไม่ถูกแสดงกลับมาบนหน้านี้ ช่องด้านบนจึงว่างเปล่าเมื่อมีอะไรถูกเก็บไว้แล้ว',
