  'settings.eventTargets.headers': 'เฮดเดอร์',
  'settings.eventTargets.headersHint': 'บรรทัดละหนึ่งเฮดเดอร์ เขียนเป็น ชื่อ: ค่า แบบเดียวกับที่เขียนกันทุกที่ ตรงนี้คือที่ของโทเคน: Authorization: Bearer … สำหรับ Matrix, X-Title หรือ Priority สำหรับ ntfy ค่าถูกเก็บแบบเดียวกับรหัสผ่านเราเตอร์ คืออยู่ใน settings.json บนเครื่องนี้ และไม่เคยถูกส่งกลับไปยังเบราว์เซอร์ คุณจะเห็นดาวแปดดวงแทน ถ้าคุณเปลี่ยนที่อยู่ ค่าที่เก็บไว้จะถูกทิ้ง ไม่ได้ถูกยกไปให้ที่อยู่ใหม่',
