  'settings.eventTargets.bodyHint': 'สิ่งที่ถูกส่งไป พร้อมตัวแปรที่ถูกเติมค่าในวินาทีที่เหตุการณ์เกิดขึ้น ปล่อยว่างไว้แล้วจะมีแต่เฮดเดอร์ออกไป ค่าจะถูกเอสเคปให้เข้ากับ Content-Type ที่คุณตั้งไว้ในเฮดเดอร์ ในเนื้อหาแบบ JSON ชื่อไฟล์ที่มีเครื่องหมายคำพูดอยู่ข้างในจึงถูกเอสเคป แทนที่จะทำให้เอกสารพัง นี่คือจุดที่คำขอเหล่านี้พังกันตอนตีสาม',
  'settings.eventTargets.events': 'เหตุการณ์',
  'settings.eventTargets.eventsHint': 'เหตุการณ์ไหนไปที่ปลายทางนี้ ตอนเริ่มต้นไม่มีอะไรถูกติ๊กไว้ สามอย่างในนั้นจะรายงานตัวอีกครั้งหลังรีสตาร์ท เพราะสิ่งที่มันจำอยู่ในหน่วยความจำ ไม่ได้อยู่บนดิสก์: คิวรายงานว่าตัวเองว่าง แคปช่าทุกอันที่ยังรออยู่รายงานตัวอีกครั้ง และบัญชีทุกบัญชีที่หมดอายุไปแล้วรายงานตัวอีกครั้ง แพ็กเกจที่เสร็จไม่ทำแบบนั้น เพราะรอบแรกหลังเริ่มทำงานเพียงจดสถานะไว้และไม่พูดอะไร',
  'settings.eventTargets.eventsNone': 'ไม่มีอะไรถูกติ๊กไว้ ปลายทางนี้จึงไม่เคยส่งอะไรเลย',
  'settings.eventTargets.eventsBurst': 'ลิงก์ที่ถูกเพิ่มเข้ามาจะทำงานหนึ่งครั้งต่อหนึ่งลิงก์ การวางสองร้อยลิงก์จึงเป็นสองร้อยข้อความ สิ่งที่คิวรับไม่ไหวจะถูกทิ้งและนับไว้ด้านล่าง แทนที่จะกองสะสมขึ้นไป',
  'settings.eventTargets.eventsReplay': 'มีเหตุการณ์ที่คุณติ๊กไว้อย่างน้อยหนึ่งอย่างที่รายงานตัวอีกครั้งหลังรีสตาร์ททุกครั้ง เพราะสิ่งที่มันจำอยู่ในหน่วยความจำ ไม่ได้อยู่บนดิสก์',
  'settings.eventTargets.attempts': 'จำนวนครั้งที่พยายามส่ง',
  'settings.eventTargets.attemptsHint': 'ข้อความหนึ่งจะถูกลองกี่ครั้งก่อนจะเลิกล้มไป 0 หมายถึงคุณไม่ออกความเห็น แล้วใช้สามครั้งตามปกติ ตัวเลขที่ใช้อยู่จริงแสดงไว้ข้างช่อง ใส่ได้ระหว่าง 1 ถึง 5 การถูกปฏิเสธจากปลายทาง โทเคนผิด หรือพาธที่ไม่มีอยู่ จะไม่ถูกลองซ้ำเลย เพราะลองครั้งที่สองก็เปลี่ยนอะไรไม่ได้ และเหตุผลอยู่ในสถานะด้านล่าง ระหว่างที่ข้อความรออยู่ ไม่มีอะไรถูกเขียนลงดิสก์ ปลายทางที่ล้มไปทั้งคืนจึงไม่มีอะไรต้องตามเก็บเมื่อมันกลับมา',
  'settings.eventTargets.attemptsDefault': '0 หมายถึงสาม',
  'settings.eventTargets.timeout': 'ขีดจำกัดเวลา (วินาที)',
