  'health.remedy.disk.low': 'โฟลเดอร์ปลายทางหนึ่งอยู่ต่ำกว่าเส้นขั้นต่ำที่คุณตั้งไว้บนหน้าการดาวน์โหลด ที่นั่นจะไม่มีอะไรใหม่เริ่มทำงาน จนกว่าจะมีที่ว่างอีกครั้ง หรือจนกว่าคุณจะลดเส้นนั้นลง สิ่งที่ทำงานอยู่แล้วไม่ถูกเส้นนั้นหยุด',
