  'health.remedy.accounts.benched': 'มีบัญชีโฮสเตอร์อย่างน้อยหนึ่งบัญชีถูกปล่อยไว้เฉย ๆ หลังเกิดข้อผิดพลาด มันจะถูกลองอีกครั้งเองเมื่อหมดเวลารอ และเวลารอจะเพิ่มเป็นสองเท่าทุกครั้ง เปิดหน้าบัญชีแล้วกดรีเฟรชที่แถวนั้น ถ้าคุณอยากรู้ตอนนี้',
