  'settings.diagnostics.fix.javaMissing': 'ไม่พบ Java อิมเมจของคอนเทนเนอร์พามาหนึ่งตัว ส่วนการติดตั้งบนเดสก์ท็อปใช้รันไทม์ที่มาด้วยหรือตัวที่อยู่ใน PATH ถ้าไม่มีมัน JDownloader ส่วนตัวจะไม่เริ่มทำงาน ลิงก์คอนเทนเนอร์ที่เข้ารหัส (.dlc, .ccf, .rsdf) จึงเปิดไม่ได้เลย ตั้ง JAVA_HOME หรือให้ KL_JD ชี้ไปที่ JDownloader ที่ทำงานอยู่ที่อื่น',
