  'settings.diagnostics.fix.notRunnable': 'พบที่ {subject} แต่มันรันไม่ได้: {error}',
  'settings.diagnostics.fix.appearedLate': 'ตอนนี้มันทำงานได้ และตอนที่อินสแตนซ์นี้เริ่มทำงานมันยังไม่อยู่ที่นั่น จึงยังไม่มีอะไรถูกส่งไปให้มัน รีสตาร์ทเพื่อรับมันเข้ามา',
  'settings.diagnostics.fix.utcFallback': 'TZ ถูกตั้งไว้ที่ {subject} และอินสแตนซ์นี้โหลดเขตนั้นไม่ได้ มันจึงถอยกลับไปเป็น UTC โดยไม่บอกไว้ที่ไหนเลย จนกว่าจะแก้เรื่องนี้ได้ ทุกช่วงเวลาในตารางจะเดินตาม UTC ตรวจตัวสะกดเทียบกับรายชื่อเขต (“Europe/Berlin”) และตรวจว่าอิมเมจมีฐานข้อมูลเขตเวลาอยู่หรือไม่',
